ointer;\n  font-weight: bold;\n  color: white;\n}\n.btn-primary {\n  background: #007bff;\n}\n.btn-primary:hover {\n  background: #0056b3;\n}\n.btn-danger {\n  background: #dc3545;\n}\n.btn-danger:hover {\n  background: #a71d2a;\n}\n.btn-success {\n  background: #28a745;\n}\n.btn-success:hover {\n  background: #218838;\n}\n.btn-warning {\n  background: #ff9800;\n}\n.btn-warning:hover {\n  background: #e68a00;\n}\n.wb-actions {\n  display: flex;\n  flex-direction: column;\n  gap: 15px;\n  margin-bottom: 20px;\n}\n.ark-btn {\n  position: relative;\n  height: 48px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  cursor: pointer;\n  border: 1px solid var(--ui-border-primary);\n  background: var(--ui-bg);\n  transition: all 0.2s ease;\n  overflow: hidden;\n}\n.ark-btn .btn-content {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  z-index: 2;\n  transition: all 0.2s;\n}\n.ark-btn .btn-text {\n  font-weight: bold;\n  letter-spacing: 1px;\n  text-transform: uppercase;\n  font-size: 0.9em;\n}\n.ark-btn.warning {\n  border-color: #ff9800;\n  color: #ff9800;\n}\n.ark-btn.warning:hover {\n  background: #ff9800;\n  color: #fff;\n}\n.ark-btn.danger {\n  border-color: #f44336;\n  color: #f44336;\n}\n.ark-btn.danger:hover {\n  background: #f44336;\n  color: #fff;\n}\n.ark-btn::after {\n  content: '';\n  position: absolute;\n  top: 0;\n  right: 0;\n  width: 0;\n  height: 0;\n  border-style: solid;\n  border-width: 0 10px 10px 0;\n  border-color: transparent currentColor transparent transparent;\n  opacity: 0.5;\n}\n.ark-btn:active {\n  transform: scale(0.98);\n}\n","\n@import './styles/theme.scss';\n\n.ark-startup-container {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  width: 100%;\n  --ui-bg: #fafafa;\n  --ui-text-main: #1a1a1a;\n  --ui-text-secondary: #2a2a2a;\n  --ui-border-primary: #e8e8e8;\n  --ui-accent: #1a1a1a;\n  --warning-accent: #ffa726;\n  --panel-width: 300px;\n}\n\n.ark-startup-container.dark-theme {\n  --ui-bg: rgba(20, 20, 20, 0.85);\n  --ui-text-main: #e0e0e0;\n  --ui-text-secondary: #b0b0b0;\n  --ui-border-primary: #444;\n  --ui-accent: #4fc3f7;\n}\n\n.ark-startup-container.transparent-theme {\n  --ui-bg: rgba(44, 47, 51, 0.4);\n  --ui-text-main: #eee;\n  --ui-text-secondary: #ccc;\n  --ui-border-primary: rgba(255, 255, 255, 0.1);\n  --ui-accent: #4fc3f7;\n}\n\n.ark-startup-container.transparent-theme .main-container {\n  backdrop-filter: blur(8px);\n}\n\n.main-container {\n  width: 100%;\n  max-width: 900px;\n  background: var(--ui-bg);\n  backdrop-filter: blur(10px);\n  border-radius: 4px;\n  border: 1px solid var(--ui-border-primary);\n  position: relative;\n  overflow: hidden;\n  transition:\n    background-color 0.3s,\n    border-color 0.3s;\n}\n\n.content-wrapper {\n  padding: 50px 40px;\n  position: relative;\n  z-index: 3;\n}\n\n.header-section {\n  text-align: center;\n  margin-bottom: 50px;\n  padding-bottom: 30px;\n  border-bottom: 1px solid var(--ui-border-primary);\n}\n\n.arknights-logo {\n  width: 300px;\n  height: auto;\n  transition: filter 0.3s;\n}\n\n.dark-theme .arknights-logo,\n.transparent-theme .arknights-logo {\n  filter: invert(1) brightness(0.8);\n}\n\n.author-info {\n  font-size: 1em;\n  color: var(--ui-text-secondary);\n  margin-bottom: 5px;\n  font-weight: 300;\n}\n\n.copyright-notice,\n.usage-instructions,\n.warning-box {\n  background: rgba(128, 128, 128, 0.1);\n  padding: 20px;\n  margin: 30px 0;\n  border-left: 3px solid var(--ui-accent);\n  font-size: 0.9em;\n  line-height: 1.8;\n  color: var(--ui-text-secondary);\n}\n\n.usage-instructions {\n  background: rgba(255, 167, 38, 0.1);\n  margin: 20px 0 30px 0;\n  border-left: 3px solid var(--warning-accent);\n}\n\n.warning-box {\n  background-color: rgba(255, 165, 0, 0.1);\n  border-left-color: var(--warning-accent);\n  margin-bottom: 20px;\n  border: 1px solid rgba(255, 165, 0, 0.5);\n  border-radius: 4px;\n}\n\n.section-title {\n  font-size: 1.5em;\n  font-weight: 500;\n  color: var(--ui-text-main);\n  margin: 40px 0 20px 0;\n  padding-bottom: 10px;\n  border-bottom: 2px solid var(--ui-accent);\n  letter-spacing: 2px;\n}\n\n.intro-desc {\n  font-size: 1em;\n  color: var(--ui-text-secondary);\n  line-height: 1.8;\n  margin-bottom: 30px;\n}\n\n.opening-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));\n  gap: 20px;\n  margin-top: 30px;\n}\n\n.opening-card {\n  background: transparent;\n  border: 1px solid var(--ui-border-primary);\n  padding: 25px;\n  cursor: pointer;\n  transition: all 0.3s ease;\n  position: relative;\n}\n\n.opening-card:hover {\n  transform: translateY(-3px);\n  border-color: var(--ui-accent);\n  background-color: rgba(128, 128, 128, 0.05);\n}\n\n.opening-title {\n  font-size: 1.2em;\n  font-weight: 500;\n  color: var(--ui-text-main);\n}\n\n.opening-info {\n  font-size: 0.85em;\n  color: var(--ui-text-secondary);\n  margin-top: 4px;\n  opacity: 0.8;\n}\n\n.info-label {\n  font-weight: bold;\n  opacity: 0.7;\n}\n\n/* Settings Panel */\n.settings-panel {\n  position: absolute;\n  top: 0;\n  right: calc(var(--panel-width) * -1);\n  width: var(--panel-width);\n  height: 100%;\n  background-color: var(--ui-bg);\n  backdrop-filter: blur(12px);\n  border-left: 1px solid var(--ui-border-primary);\n  z-index: 1000;\n  padding: 20px;\n  transition: right 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);\n  box-sizing: border-box; /* Prevent padding from adding to width */\n}\n\n.settings-panel.is-open {\n  right: 0;\n}\n\n/* Overlay Backdrop */\n.settings-overlay {\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  background-color: rgba(0, 0, 0, 0.5);\n  z-index: 999; /* Below panel (1000), above content */\n  backdrop-filter: blur(2px);\n}\n\n.settings-tab {\n  position: absolute;\n  top: 20px;\n  right: 0px;\n  width: 50px;\n  height: 50px;\n  background-color: var(--ui-bg);\n  border: 1px solid var(--ui-border-primary);\n  border-right: none;\n  border-top-left-radius: 6px;\n  border-bottom-left-radius: 6px;\n  cursor: pointer;\n  z-index: 1001;\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  color: var(--ui-text-secondary);\n  transition: right 0.4s cubic-bezier(0.25, 0.8, 0.25, 1);\n}\n\n.settings-tab.is-open {\n  right: var(--panel-width);\n}\n\n.settings-divider {\n  height: 1px;\n  background-color: var(--ui-border-primary);\n  margin: 20px 0;\n}\n\n.theme-buttons-container {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  margin-top: 15px;\n}\n\n.theme-button {\n  width: 100%;\n  height: 50px;\n  border-radius: 4px;\n  cursor: pointer;\n  border: 2px solid var(--ui-border-primary);\n  position: relative;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.theme-button.light {\n  background-color: #fafafa;\n  color: #1a1a1a;\n}\n.theme-button.dark {\n  background-color: #2a2a2a;\n  color: #e0e0e0;\n}\n.theme-button.transparent {\n  background: linear-gradient(135deg, rgba(200, 200, 200, 0.1), rgba(100, 100, 100, 0.1));\n  color: var(--ui-text-main);\n  backdrop-filter: blur(4px);\n}\n.theme-button.active {\n  border-color: var(--ui-accent);\n}\n\n.theme-button {\n  padding: 5px;\n}\n\n.theme-button span {\n  position: absolute;\n  bottom: 5px;\n  right: 10px;\n  font-size: 0.8em;\n  font-weight: bold;\n}\n\n.setting-item {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 20px;\n}\n\nh3 {\n  color: var(--ui-text-main);\n  font-weight: 500;\n  font-size: 1.2em;\n}\n\n/* --- Arknights Style UI --- */\n\n/* Status Display */\n.wb-status-display {\n  padding: 15px;\n  margin-bottom: 20px;\n  background: rgba(0, 0, 0, 0.05);\n  border-left: 4px solid #999;\n  position: relative;\n  overflow: hidden;\n}\n\n.wb-status-display .status-label {\n  font-size: 0.7em;\n  letter-spacing: 2px;\n  color: var(--ui-text-secondary);\n  margin-bottom: 5px;\n}\n\n.wb-status-display .status-value {\n  font-size: 1.2em;\n  font-weight: bold;\n  letter-spacing: 1px;\n}\n\n.wb-status-display .status-diff {\n  margin-top: 8px;\n  font-size: 0.8em;\n  opacity: 0.8;\n  line-height: 1.4;\n}\n\n.wb-status-display .status-decor {\n  position: absolute;\n  top: 0;\n  right: 0;\n  width: 20px;\n  height: 20px;\n  background: linear-gradient(45deg, transparent 50%, rgba(255, 255, 255, 0.1) 50%);\n}\n\n.status-green {\n  border-left-color: #4caf50;\n  color: #4caf50;\n  background: rgba(76, 175, 80, 0.05);\n}\n.status-blue {\n  border-left-color: #2196f3;\n  color: #2196f3;\n  background: rgba(33, 150, 243, 0.05);\n}\n.status-orange {\n  border-left-color: #ff9800;\n  color: #ff9800;\n  background: rgba(255, 152, 0, 0.05);\n}\n\n/* Mobile Responsive */\n@media (max-width: 768px) {\n  .ark-startup-container {\n    /*\n      Compress sidebar width to 210px (Final Polish).\n      On a 360px screen, this leaves 150px (50px button + 100px overlay),\n      providing a very comfortable interaction zone.\n    */\n    --panel-width: 210px;\n  }\n\n  /* Reduce panel internal padding to maximize space in the narrower sidebar */\n  .settings-panel {\n    padding: 12px;\n  }\n\n  .wb-status-display {\n    padding: 10px;\n  }\n\n  /* Adjust font sizes for narrower panel */\n  .wb-status-display .status-value {\n    font-size: 1em; /* Slightly smaller for 210px */\n  }\n\n  .ark-btn .btn-text {\n    font-size: 0.8em; /* Ensure text fits in 210px */\n  }\n\n  /* Main Content Adjustments */\n  .content-wrapper {\n    padding: 30px 15px; /* Reduce padding to prevent overflow */\n  }\n\n  .arknights-logo {\n    width: 80%; /* Responsive logo width */\n    max-width: 300px;\n  }\n\n  .opening-grid {\n    grid-template-columns: 1fr; /* Single column on mobile */\n  }\n\n  /* Fix button text wrapping */\n  .ark-btn {\n    height: auto;\n    min-height: 48px;\n    padding: 10px;\n  }\n\n  .ark-btn .btn-content {\n    flex-wrap: wrap;\n    justify-content: center;\n    text-align: center;\n  }\n}\n"],"sourceRoot":""}]);
